/// One design icon in its 15 x 15 box, drawn in `color`.
struct PullRequestIconView: View {
    let icon: PullRequestIcon
    let color: NSColor

    var body: some View {
        ZStack {
            ForEach(Array(icon.paths.enumerated()), id: \.offset) { _, path in
                if icon.isStroked {
                    path.stroke(color.swiftUI, style: StrokeStyle(lineWidth: 1, lineCap: .round, lineJoin: .round))
                } else {
                    path.fill(color.swiftUI)
                }
            }
        }
        .frame(width: PullRequestIcon.side, height: PullRequestIcon.side)
    }
}
